# Familie Tan zoals compleet gemaakt in spel 3 (moeder, vader, dochtertje + gekocht biggetje)
def moeder_tan(x,y,s=1.0): return persoon(x,y,'#C43B38','#E8B48A','bh-lang','#2B1A0E',jurk=True,acc=('acc-nonla',),s=s)
def vader_tan(x,y,s=1.0):  return persoon(x,y,'#39D353','#E8B48A','bh-kort','#2B1A0E',acc=('acc-pet',),s=s)
def meisje_tan(x,y,s=1.0): return persoon(x,y,'#5BC0EB','#E8B48A','bh-lang','#FFC93C',jurk=True,kind=True,acc=('acc-rijsthoed-kind',),s=s)
def big_tan(x,y,s=1.0):    return dier(x,y,'biggetje',s)
def pino_foto(x,y,s=1.0,flip=False):
    f=' scale(-1 1) translate(-48 0)' if flip else ''
    return f'<g transform="translate({x} {y}) scale({s}){f}">'+use('pino-foto',0,0,48,72)+'</g>'
def sil(x,y,wie,kleur,s=1.0):
    return f'<g transform="translate({x} {y}) scale({s})">'+use('sil-'+wie,0,0,24,32,kleur)+'</g>'
